:root {
  /* Colors */
  --color-jet-canvas: #000000;
  --color-graphite-card: #181818;
  --color-iron-tile: #262628;
  --color-paper: #ffffff;
  --color-carbon-label: #0b0b0c;
  --color-onyx-ink: #171717;
  --color-slate-body: #3f3f3f;
  --color-ash-meta: #707070;
  --color-pewter-caption: #969696;
  --color-fog-ink: #e8e8e8;
  --color-frosted-hairline: #ffffff1a;
  --color-cobalt-eyebrow: #0064dc;
  --color-mint-pulse: #4ade80;

  /* Typography — Font Families */
  --font-open-runde: "Open Runde", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-open-runde-tabular: "Open Runde Tabular", "Open Runde", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-apple-system: -apple-system, ui-sans-serif, system-ui, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.3;
  --tracking-small: -0.16px;
  --text-caption: 12px;
  --leading-caption: 1.4;
  --tracking-caption: -0.16px;
  --text-body-sm: 13.5px;
  --leading-body-sm: 1.45;
  --tracking-body-sm: -0.16px;
  --text-body: 15.5px;
  --leading-body: 1.4;
  --tracking-body: -0.16px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.65;
  --tracking-body-lg: -0.16px;
  --text-subheading: 15px;
  --leading-subheading: 1.6;
  --tracking-subheading: -0.225px;
  --text-heading-sm: 19px;
  --leading-heading-sm: 1.3;
  --tracking-heading-sm: -0.42px;
  --text-heading: 21px;
  --leading-heading: 1.2;
  --tracking-heading: -0.63px;
  --text-display: 28px;
  --leading-display: 1.15;
  --tracking-display: -0.98px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-5: 5px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-9: 9px;
  --spacing-10: 10px;
  --spacing-11: 11px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-15: 15px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-64: 64px;
  --spacing-120: 120px;

  /* Layout */
  --layout-max-width: 900px;
  --layout-hero-column: 400px;
  --layout-section-gap: 120px;
  --layout-section-gap-mobile: 64px;
  --layout-card-padding: 24px;
  --layout-element-gap: 8px;
  --layout-nav-height: 60px;

  /* Border Radius */
  --radius-sm-3: 1.5px;
  --radius-sm-2: 3px;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl-2: 14px;
  --radius-xl: 16px;
  --radius-2xl: 20px;
  --radius-2xl-2: 22px;
  --radius-3xl: 24px;
  --radius-3xl-2: 28px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-cards: 24px;
  --radius-sections: 28px;
  --radius-small-cards: 20px;
  --radius-inner-tiles: 16px;
  --radius-nav: 14px;
  --radius-buttons: 999px;
  --radius-pills: 999px;
  --radius-tags: 999px;
  --radius-badges: 999px;
  --radius-avatars: 50%;
  --radius-images: 12%;
  --radius-inputs: 0px;
  --radius-small-elements: 1.5px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px rgba(255, 255, 255, 0.05);
  --shadow-subtle-2: inset 0 1px 0 0 rgba(255, 255, 255, 0.06);
  --shadow-subtle-3: inset 0 0 0 1px rgba(0, 0, 0, 0.06);
  --shadow-sm: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
  --shadow-sm-2: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  --shadow-md: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
  --shadow-md-2: 0 0 0 2px #181818;
  --shadow-lg: 0 4px 12px 0 rgba(0, 0, 0, 0.4);
  --shadow-xl: inset 0 0 0 1px rgba(255, 255, 255, 0.08), inset 0 1px 0 0 rgba(255, 255, 255, 0.05), 0 30px 60px -24px rgba(0, 0, 0, 0.7), 0 2px 8px 0 rgba(0, 0, 0, 0.2);

  /* Surfaces */
  --surface-jet-canvas: #000000;
  --surface-graphite-card: #181818;
  --surface-iron-tile: #262628;
  --surface-paper: #ffffff;
}

